const READY = '__complete__';

const scopedUrl = file => new URL(file, self.registration.scope).toString();
const notify = async payload => {
  const clients = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
  clients.forEach(client => client.postMessage({ source: 'galaxy-public-viewer', version: VERSION, ...payload }));
};

async function populateAtomicCache() {
  if (await caches.has(FINAL_CACHE)) {
    const existing = await caches.open(FINAL_CACHE);
    if (await existing.match(scopedUrl(READY))) return true;
  }
  await caches.delete(TEMP_CACHE);
  const temporary = await caches.open(TEMP_CACHE);
  const previous = [];
  for (const name of await caches.keys()) {
    if (!name.startsWith(CACHE_PREFIX) || name.endsWith('-installing') || name === FINAL_CACHE) continue;
    const cache = await caches.open(name);
    const response = await cache.match(scopedUrl('offline-manifest.json'));
    if (response) { try { previous.push({ cache, manifest: await response.json() }); } catch {} }
  }
  let completed = 0;
  try {
    for (let offset = 0; offset < FILES.length; offset += 8) {
      const batch = FILES.slice(offset, offset + 8);
      await Promise.all(batch.map(async file => {
        const url = scopedUrl(file);
        let response;
        for (const old of previous) {
          if (HASHES[file] && old.manifest.hashes?.[file] === HASHES[file]) response = await old.cache.match(url);
          if (response) break;
        }
        if (!response) response = await fetch(url, { cache: 'reload', credentials: 'omit' });
        if (!response.ok) throw new Error('Offline asset returned ' + response.status + ': ' + file);
        if (HASHES[file]) {
          const digest = await crypto.subtle.digest('SHA-256', await response.clone().arrayBuffer());
          const hex = [...new Uint8Array(digest)].map(byte => byte.toString(16).padStart(2, '0')).join('');
          if (hex !== HASHES[file]) throw new Error('Offline checksum mismatch: ' + file);
        }
        await temporary.put(url, response);
      }));
      completed += batch.length;
      await notify({ type: 'CACHE_PROGRESS', completed, total: FILES.length });
    }
    const finalCache = await caches.open(FINAL_CACHE);
    for (const request of await temporary.keys()) {
      const response = await temporary.match(request);
      if (!response) throw new Error('Offline cache copy failed.');
      await finalCache.put(request, response);
    }
    await finalCache.put(scopedUrl(READY), new Response(VERSION));
    await caches.delete(TEMP_CACHE);
    // Activation claims the clients before announcing offline readiness.
    return true;
  } catch (error) {
    await caches.delete(TEMP_CACHE);
    await caches.delete(FINAL_CACHE);
    await notify({ type: 'CACHE_ERROR', message: error?.message || String(error), completed, total: FILES.length });
    return false;
  }
}

self.addEventListener('install', event => {
  event.waitUntil(populateAtomicCache().then(ready => { if (!ready) throw new Error('Incomplete offline release'); return self.skipWaiting(); }));
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const ready = await caches.has(FINAL_CACHE) && Boolean(await (await caches.open(FINAL_CACHE)).match(scopedUrl(READY)));
    const names = await caches.keys();
    if (ready) {
      await Promise.all(names
        .filter(name => name.startsWith(CACHE_PREFIX) && name !== FINAL_CACHE)
        .map(name => caches.delete(name)));
    }
    await self.clients.claim();
    await notify(ready
      ? { type: 'CACHE_READY', completed: FILES.length, total: FILES.length }
      : { type: 'CACHE_ERROR', message: 'Pełna kopia offline nie zmieściła się w pamięci przeglądarki. Aktualna mapa nadal działa online.', completed: 0, total: FILES.length });
  })());
});

self.addEventListener('message', event => {
  if (event.data?.type === 'GET_CACHE_STATUS') {
    event.waitUntil(caches.open(FINAL_CACHE).then(cache => cache.match(scopedUrl(READY))).then(ready => notify({
      type: ready ? 'CACHE_READY' : 'CACHE_ERROR',
      completed: ready ? FILES.length : 0,
      total: FILES.length,
      ...(!ready ? { message: 'Pełna kopia offline nie jest dostępna. Aktualna mapa nadal działa online.' } : {}),
    })));
  }
});

const admittedCaches = new Map();
const cachedFallback = async (request, navigation = false) => {
  const names = (await caches.keys())
    .filter(name => name.startsWith(CACHE_PREFIX) && !name.endsWith('-installing'))
    .sort((left, right) => right.localeCompare(left));
  for (const name of names) {
    let cache = admittedCaches.get(name);
    if (!cache) {
      cache = await caches.open(name);
      const manifestResponse = await cache.match(scopedUrl('offline-manifest.json'));
      if (!manifestResponse) continue;
      const manifest = await manifestResponse.json();
      if (manifest.hashes && !(await cache.match(scopedUrl(READY)))) continue;
      admittedCaches.set(name, cache);
    }
    const cached = navigation
      ? await cache.match(scopedUrl('index.html'))
      : await cache.match(request, { ignoreSearch: true });
    if (cached) return cached;
  }
  return null;
};

self.addEventListener('fetch', event => {
  const request = event.request;
  const url = new URL(request.url);
  if (request.method !== 'GET') return;
  if (/\/api(?:\/|$)/.test(url.pathname)) {
    event.respondWith(Promise.resolve(new Response('Public viewer API is disabled.', { status: 403 })));
    return;
  }
  if (url.origin !== self.location.origin || !url.href.startsWith(self.registration.scope)) return;
  if (request.mode === 'navigate') {
    event.respondWith((async () => (await cachedFallback(request, true)) || fetch(request, { cache: 'no-store' }))());
    return;
  }
  event.respondWith((async () => (await cachedFallback(request)) || fetch(request, { cache: 'no-store' }))());
});
